from _lib import *
MM="Manuel des Monstres 5e (2014), entrée « %s »"
D="Dans D&D 5e, "
SKT="Storm King’s Thunder (2016)"
VGM="Volo’s Guide to Monsters (2016)"
C("gea-001",1,D+"quel géant, le plus fruste, vit dans les collines et lance des rochers ?",["Le géant des collines","Le géant du feu","Le géant des nuages","Le géant des tempêtes"],"Le géant des collines (FP 5) est glouton et peu raffiné ; il lance des rochers pour attaquer à distance.",MM%"Géant des collines")
C("gea-002",1,D+"quel géant habite les glaciers et les terres glacées ?",["Le géant du givre","Le géant des collines","Le géant de pierre","Le géant du feu"],"Le géant du givre (FP 8) est un pillard des régions arctiques et des montagnes enneigées.",MM%"Géant du givre")
C("gea-003",2,D+"quel géant forge des armes dans les volcans ?",["Le géant du feu","Le géant de pierre","Le géant des nuages","Le géant du givre"],"Le géant du feu (FP 9) est un forgeron et un guerrier discipliné qui vit près des volcans et des forges.",MM%"Géant du feu")
C("gea-004",2,D+"quel géant bâtit ses châteaux au-dessus des nuages ?",["Le géant des nuages","Le géant des collines","Le géant du feu","Le géant de pierre"],"Le géant des nuages (FP 9) vit sur des sommets ou dans des châteaux flottant sur les nuages ; il aime le luxe.",MM%"Géant des nuages")
C("gea-005",2,D+"quel géant est le plus puissant des six, avec un FP de 13 ?",["Le géant des tempêtes","Le géant de pierre","Le géant des nuages","Le géant du feu"],"Le géant des tempêtes (FP 13) domine l’Ordning ; il vit près des océans ou sur des plateaux battus par l’orage.",MM%"Géant des tempêtes")
C("gea-006",3,D+"comment appelle-t-on la hiérarchie sociale des géants ?",["L’Ordning","La Cabale","L’Ordalie","Le Conclave"],"L’Ordning classe les géants du plus bas (collines) au plus haut (tempêtes) ; chacun doit connaître son rang.",SKT+", chap. 1")
C("gea-007",2,D+"quel géant sculpte la pierre et vit dans des cavernes en montagne ?",["Le géant de pierre","Le géant des collines","Le géant des nuages","Le géant du givre"],"Le géant de pierre (FP 7) est un artiste discret qui sculpte la pierre et vit dans des cavernes.",MM%"Géant de pierre")
C("gea-008",2,D+"que stoppe la régénération d’un troll ?",["Les dégâts d’acide et de feu","Les dégâts de foudre","Les dégâts de froid","Les dégâts contondants"],"Un troll qui subit de l’acide ou du feu ne régénère pas à son prochain tour : il peut alors mourir.",MM%"Troll")
C("gea-009",1,D+"quelle capacité rend des PV au troll à chaque tour ?",["La régénération","La vision aveugle","La résurrection","La furie"],"La Régénération rend 10 PV par tour, tant que le troll n’a pas subi d’acide ni de feu.",MM%"Troll")
C("gea-010",2,D+"quel géant à deux têtes est apparenté à l’ogre ?",["L’ettin","Le troll","Le cyclope","Le hobgobelin"],"L’ettin (FP 4) est un géant bicéphale ; chaque tête monte la garde pendant que l’autre dort.",MM%"Ettin")
C("gea-011",3,"Dans le panthéon des géants de D&D, quel dieu est vénéré par les géants du givre ?",["Thrym","Annam","Memnor","Surtur"],"Thrym est le dieu des géants du givre ; Surtur est celui des géants du feu.",SKT+", chap. 1 « L’Ordning »")
C("gea-012",3,"Dans le panthéon des géants de D&D, quel dieu est vénéré par les géants du feu ?",["Surtur","Thrym","Memnor","Skoraeus"],"Surtur est le dieu des forges et des géants du feu.",SKT+", chap. 1 « L’Ordning »")
C("gea-013",3,"Dans le panthéon des géants de D&D, quel dieu est le Père de Tous ?",["Annam","Surtur","Thrym","Grolantor"],"Annam le Père de Tous est le créateur du panthéon des géants ; ses enfants sont les dieux de chaque type de géant.",SKT+", chap. 1")
C("gea-014",2,D+"quel peuple jouable a une ascendance géante ?",["Les goliaths","Les nains","Les orques","Les drakéides"],"Les goliaths descendent des géants et ont un physique imposant ; ils apparaissent dans Volo.",VGM+", chap. 2 « Goliath »")
C("gea-015",2,D+"quelle est la taille d’un ogre ?",["Grande","Moyenne","Très grande","Gigantesque"],"L’ogre (FP 2) est de taille Grande ; les vrais géants sont de taille Très grande (Huge).",MM%"Ogre")
C("gea-016",2,D+"quelle est la taille d’un géant des collines ?",["Très grande (Huge)","Gigantesque","Grande","Moyenne"],"Les six types de géants sont de taille Très grande.",MM%"Géant des collines")
C("gea-017",2,D+"quels dégâts inflige un rocher lancé par un géant ?",["Contondants","Tranchants","Perforants","De foudre"],"Un rocher inflige des dégâts contondants (3d10 + Force pour un géant des collines).",MM%"Géant des collines")
C("gea-018",3,D+"quel géant a la Force la plus basse des six types ?",["Le géant des collines","Le géant du feu","Le géant de pierre","Le géant du givre"],"Le géant des collines a une Force de 21, la plus faible ; celle du géant des tempêtes atteint 29.",MM%"Géant des collines")
C("gea-019",3,D+"quelle série de modules, publiée en 1978, oppose les aventuriers aux géants ?",["Against the Giants","Queen of the Spiders","Temple of Elemental Evil","White Plume Mountain"],"Against the Giants (G1-G3, TSR, 1978) est une série d’aventures de D&D, avec des géants des collines, du givre et du feu.",D+"Against the Giants (TSR, 1978-1981)")
C("gea-020",2,D+"quelle aventure de 2016 met en scène une menace de géants ?",["Storm King’s Thunder","La Malédiction de Strahd","Tomb of Annihilation","Out of the Abyss"],"Storm King’s Thunder (2016) lance les héros dans la crise de l’Ordning.",SKT+", introduction")
C("gea-021",3,"Dans Storm King’s Thunder, quel est le titre du roi des géants des tempêtes ?",["Le Roi de la tempête (Hekaton)","Le Roi de la montagne","Le Roi du givre","Le Seigneur des nuages"],"Le roi Hekaton est le roi des tempêtes ; sa disparition ouvre l’aventure.",SKT+", chap. 1")
C("gea-022",3,D+"quel géant a une Force de 29 ?",["Le géant des tempêtes","Le géant du feu","Le géant des nuages","Le géant de pierre"],"Le géant des tempêtes a une Force de 29, ce qui le place au sommet de la liste.",MM%"Géant des tempêtes")
C("gea-023",3,D+"quel géant a la CA la plus élevée (18) ?",["Le géant du feu","Le géant du givre","Le géant des tempêtes","Le géant de pierre"],"Le géant du feu porte une armure de plates : CA 18.",MM%"Géant du feu")
C("gea-024",3,D+"quel géant a 200 PV en moyenne ?",["Le géant des nuages","Le géant du givre","Le géant du feu","Le géant de pierre"],"Le géant des nuages a 200 PV (16d12 + 96).",MM%"Géant des nuages")
C("gea-025",2,D+"quelle arme préfère le géant du feu ?",["Une épée à deux mains","Un arc long","Une masse d’armes","Une faux"],"Le géant du feu manie une épée à deux mains (greatsword) avec laquelle il frappe deux fois par tour.",MM%"Géant du feu")
C("gea-026",3,D+"combien de types de géants « classiques » le Manuel des Monstres décrit-il ?",["Six","Quatre","Huit","Trois"],"Six : collines, pierre, givre, feu, nuages et tempêtes.",MM%"Géants")
C("gea-027",2,D+"quelle capacité permet au géant de pierre de renvoyer un rocher ?",["Capture de rocher","Régénération","Vision aveugle","Fureur"],"Capture de rocher (Rock Catching) : il peut attraper ou dévier un rocher lancé sur lui.",MM%"Géant de pierre")
C("gea-028",2,D+"quelle créature géante vit aussi sous l’eau, dans l’océan ?",["Le géant des tempêtes","Le géant du feu","Le géant de pierre","Le géant des collines"],"Les géants des tempêtes vivent souvent près ou dans les océans et peuvent respirer sous l’eau.",MM%"Géant des tempêtes")
C("gea-029",2,D+"quel type de créature est un géant ?",["Géant","Humanoïde","Monstruosité","Aberration"],"Les six géants, l’ogre et l’ettin appartiennent au type géant (giant) ; l’ogre aussi.",MM%"Géant")
C("gea-030",2,D+"quelle créature à régénération se bat souvent aux côtés des ogres ?",["Le troll","Le hobgobelin","Le gnoll","Le kobold"],"Le troll est un monstre de la forêt, souvent allié aux ogres et aux géants.",MM%"Troll")
